<?php
namespace App\Http\Controllers\Configuration;
use App\Http\Controllers\Controller; use App\Models\Role; use App\Services\Audit\ActivityLogService; use Illuminate\Http\Request; use Illuminate\Validation\Rule;
class RoleController extends Controller { public function __construct(){ $this->middleware('menu.permission:config.roles,view')->only('index');$this->middleware('menu.permission:config.roles,create')->only(['create','store']);$this->middleware('menu.permission:config.roles,edit')->only(['edit','update']); }
 public function index(){return view('configuration.roles.index',['rows'=>Role::withCount('users')->orderBy('code')->paginate(30)]);} public function create(){return view('configuration.roles.form',['record'=>new Role,'isEdit'=>false]);}
 public function store(Request $r,ActivityLogService $audit){$d=$r->validate(['code'=>['required','string','max:100',Rule::unique('roles','code')],'name'=>['required','string','max:255'],'description'=>['nullable','string'],'is_active'=>['required','boolean']]);$role=Role::create($d);$audit->record('config.roles','create',$role,[],$role->toArray());return redirect()->route('config.roles.index')->with('success','Role created.');}
 public function edit(Role $role){return view('configuration.roles.form',['record'=>$role,'isEdit'=>true]);} public function update(Request $r,Role $role,ActivityLogService $audit){$d=$r->validate(['code'=>['required','string','max:100',Rule::unique('roles','code')->ignore($role->id)],'name'=>['required','string','max:255'],'description'=>['nullable','string'],'is_active'=>['required','boolean']]);$before=$role->toArray();$role->update($d);$audit->record('config.roles','update',$role,$before,$role->fresh()->toArray());return redirect()->route('config.roles.index')->with('success','Role updated.');}
}
